1	<?php
2	/**
3	 * Uprava objednavky – zmena stavu a slevy.
4	 *
5	 * ?id=<uuid>
6	 *
7	 * Puvodne (2015) se tu dalo upravovat vsechno vcetne polozek, od 2024
8	 * objednavky zaklada novy e-shop, takze tu zustal jen stav a sleva.
9	 * Obchodaci to pouzivaji, kdyz zakaznik zaplati prevodem a nic se nesparuje.
10	 */
11	
12	global $db;
13	legacy_db();
14	auth_require('obchod');
15	
16	$id = get_param('id');
17	if ($id == '') {
18	    $id = post_param('id');
19	}
20	
21	$order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
22	if ($order === null) {
23	    echo '<p class="err">Objednávka nenalezena.</p>';
24	    return;
25	}
26	
27	$errors = array();
28	$msg = '';
29	
30	if (is_post()) {
31	    $newStatus = post_param('status');
32	    $discount = post_param('discount');
33	
34	    // --- zmena stavu ---
35	    if ($newStatus != '' && $newStatus != $order['status']) {
36	        if (!isset($GLOBALS['ORDER_STATES'][$newStatus])) {
37	            $errors[] = 'Neplatný stav';
38	        } else {
39	            // obchodaci obcas vraceji stornovane zpet – zakazano (2016, po incidentu)
40	            if ($order['status'] == 'cancelled' && !auth_has_role('admin')) {
41	                $errors[] = 'Stornovanou objednávku může obnovit jen admin';
42	            } else {
43	                $db->exec("UPDATE orders SET status = '" . $newStatus . "' WHERE id = '" . $id . "'");
44	
45	                // pri potvrzeni doplnit datum, pokud chybi (stare objednavky)
46	                if ($newStatus == 'confirmed' && $order['placed_at'] === null) {
47	                    $db->exec("UPDATE orders SET placed_at = '" . date('Y-m-d H:i:s') . "' WHERE id = '" . $id . "'");
48	                }
49	
50	                audit_log('order', $id, 'status', array('from' => $order['status'], 'to' => $newStatus));
51	
52	                // mail zakaznikovi pri odeslani
53	                if ($newStatus == 'shipped') {
54	                    $c = $db->one("SELECT email FROM customers WHERE id = '" . $order['customer_id'] . "'");
55	                    if ($c) {
56	                        send_mail($c['email'], 'Vaše objednávka byla odeslána', "Dobrý den,\n\nvaše objednávka " . $id . " byla právě odeslána.\n");
57	                    }
58	                }
59	                // TODO: pri 'cancelled' uvolnit rezervace ve skladu (cron to taky nedela)
60	                $msg .= 'Stav změněn na ' . order_state_label($newStatus) . '. ';
61	            }
62	        }
63	    }
64	
65	    // --- sleva ---
66	    if ($discount !== '') {
67	        $discountCents = kc2hal($discount);
68	        if ($discountCents < 0) {
69	            $errors[] = 'Sleva nemůže být záporná';
70	        } elseif ($discountCents != (int) $order['discount_amount_in_cents']) {
71	            $sum = order_total($id);
72	            if ($discountCents > $sum) {
73	                // sleva vetsi nez objednavka – povolime, ale upozornime (pozadavek obchodu 2017)
74	                $msg .= 'Pozor: sleva je vyšší než hodnota objednávky! ';
75	            }
76	            $db->exec("UPDATE orders SET discount_amount_in_cents = " . $discountCents . ", discount_currency = '" . $order['currency'] . "' WHERE id = '" . $id . "'");
77	            audit_log('order', $id, 'discount', array('from' => (int) $order['discount_amount_in_cents'], 'to' => $discountCents));
78	            $msg .= 'Sleva uložena. ';
79	        }
80	    }
81	
82	    // poznamka k uprave
83	    $note = post_param('note');
84	    if ($note != '') {
85	        $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES ('" . $id . "', '" . auth_login_name() . "', " . $db->quote($note) . ", '" . date('Y-m-d H:i:s') . "')");
86	    }
87	
88	    cache_delete('dashboard_stats');
89	
90	    // znovu nacist
91	    $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
92	}
93	
94	$items = $db->query("SELECT i.*, p.name FROM order_items i LEFT JOIN products p ON p.id = i.product_id WHERE i.order_id = '" . $id . "'");
95	$sum = order_total($id);
96	
97	$pageTitle = 'Úprava objednávky';
98	include LEGACY_TEMPLATES . '/partials/old_header.php';
99	?>
100	<h1>Úprava objednávky <?php echo h($order['id']); ?></h1>

