27	use PHPUnit\Framework\Attributes\CoversClass;
28	use PHPUnit\Framework\Attributes\Test;
29	use PHPUnit\Framework\TestCase;
30	
31	#[CoversClass(Order::class)]
32	final class OrderTest extends TestCase
33	{
34	    #[Test]
35	    public function placedOrderIsDraftAndRecordsOrderPlaced(): void
36	    {
37	        $order = Order::place(OrderId::generate(), CustomerId::generate());
38	
39	        self::assertSame(OrderStatus::Draft, $order->status);
40	        $events = $order->releaseEvents();
41	        self::assertCount(1, $events);
42	        self::assertInstanceOf(OrderPlaced::class, $events[0]);
43	    }
44	
45	    #[Test]
46	    public function sameProductIsAddedToExistingItem(): void
47	    {
48	        $order = $this->draftOrder();
49	        $order->releaseEvents();
50	        $productId = ProductId::generate();
51	
52	        $order->addItem($productId, 1, $this->czk(500_00));
53	        $order->addItem($productId, 2, $this->czk(500_00));
54	
55	        self::assertCount(1, $order->items);
56	        self::assertSame(3, $order->items[0]->quantity);
57	        self::assertContainsOnlyInstancesOf(OrderItemAdded::class, $order->releaseEvents());
58	    }
59	
60	    #[Test]
61	    public function itemCannotBeAddedToConfirmedOrder(): void
62	    {
63	        $order = $this->confirmedOrder();
64	
65	        $this->expectException(InvalidOrderStateTransitionException::class);
66	        $order->addItem(ProductId::generate(), 1, $this->czk(100_00));
67	    }
68	
69	    #[Test]
70	    public function itemInOtherCurrencyIsRejected(): void
71	    {
72	        $order = $this->draftOrder();
73	
74	        $this->expectException(CurrencyMismatchException::class);
75	        $order->addItem(ProductId::generate(), 1, new Money(100_00, Currency::EUR));
76	    }
77	
78	    #[Test]
79	    public function itemQuantityChangesInDraftOrder(): void
80	    {
81	        $order = $this->draftOrder();
82	        $productId = ProductId::generate();
83	        $order->addItem($productId, 2, $this->czk(300_00));
84	
85	        $order->changeItemQuantity($productId, 5);
86	
87	        self::assertSame(5, $order->items[0]->quantity);
88	        self::assertSame(1500_00, $order->totalAmount()->amountInCents);
89	    }
90	
91	    #[Test]
92	    public function itemQuantityCannotChangeInConfirmedOrder(): void
93	    {
94	        $order = $this->confirmedOrder();
95	
96	        $this->expectException(InvalidOrderStateTransitionException::class);
97	        $order->changeItemQuantity($order->items[0]->productId, 1);
98	    }
99	
100	    #[Test]
101	    public function itemQuantityMustBePositive(): void
102	    {
103	        $order = $this->draftOrder();
104	        $productId = ProductId::generate();
105	        $order->addItem($productId, 2, $this->czk(300_00));
106	
107	        $this->expectException(InvalidQuantityException::class);
108	        $order->changeItemQuantity($productId, 0);
109	    }
110	
111	    #[Test]
112	    public function quantityOfMissingItemCannotChange(): void
113	    {
114	        $order = $this->draftOrder();
115	
116	        $this->expectException(OrderItemNotFoundException::class);
117	        $order->changeItemQuantity(ProductId::generate(), 1);
118	    }
119	
120	    #[Test]
121	    public function itemIsRemovedFromDraftOrder(): void
122	    {
123	        $order = $this->draftOrder();
124	        $keyboard = ProductId::generate();
