8	
9	class BaseController
10	{
11	    protected $title = 'Administrace';
12	
13	    public function __construct()
14	    {
15	        // zajisti, ze jsou nactene knihovny (kdyz se controller pouzije samostatne)
16	        if (!function_exists('legacy_db')) {
17	            require_once __DIR__ . '/../bootstrap.php';
18	        }
19	    }
20	
21	    /**
22	     * Vyrenderuje PHP sablonu z templates/ a vrati HTML.
23	     */
24	    public function render($template, array $vars = array())
25	    {
26	        $file = LEGACY_TEMPLATES . '/' . $template . '.php';
27	        if (!file_exists($file)) {
28	            return '<p>Chybí šablona ' . h($template) . '</p>';
29	        }
30	        extract($vars);
31	        ob_start();
32	        include $file;
33	
34	        return ob_get_clean();
35	    }
36	
37	    /**
38	     * Sablona zabalena do layoutu (hlavicka, menu, paticka).
39	     */
40	    public function renderLayout($template, array $vars = array(), $title = null)
41	    {
42	        $content = $this->render($template, $vars);
43	
44	        return $this->render('layout', array(
45	            'content' => $content,
46	            'title'   => $title !== null ? $title : $this->title,
47	            'flashes' => flash_messages(),
48	        ));
49	    }
50	
