57	    {
58	        return post_param($name, $default);
59	    }
60	
61	    protected function redirect($url)
62	    {
63	        redirect($url);
64	
65	        return '';
66	    }
67	
68	    protected function notFound($msg = 'Nenalezeno')
69	    {
70	        $GLOBALS['LEGACY_STATUS'] = 404;
71	
72	        return $this->renderLayout('partials/message', array('message' => $msg), 'Nenalezeno');
73	    }
74	}
