#[Test]
public function orderCanBeCancelledFromLegacyAdmin(): void
{
    $orders = self::getContainer()->get(OrderRepository::class);
    $stockItems = self::getContainer()->get(StockItemRepository::class);

    $order = Order::place(OrderId::generate(), CustomerId::generate());
    $order->addItem(
        \App\Ordering\Domain\ValueObject\ProductId::fromString(Catalog::KEYBOARD),
        2,
        new Money(300_00, Currency::CZK),
    );
    $order->confirm();
    $orders->save($order);

    $available = $stockItems->get(\App\Ordering\Domain\ValueObject\ProductId::fromString(Catalog::KEYBOARD))->available();

    $this->client->request(
        'GET',
        '/admin/legacy/order_edit?id=' . $order->id->value,
    );
    $this->client->submitForm('Uložit', [
        'status' => 'cancelled',
    ]);

    self::assertResponseIsSuccessful();
    self::assertSelectorTextContains('p.msg', 'stornována');
    self::getContainer()->get(EntityManagerInterface::class)->clear();
    $cancelled = $orders->get($order->id);
    self::assertSame(OrderStatus::Cancelled, $cancelled->status);

    $newAvailable = $stockItems->get(\App\Ordering\Domain\ValueObject\ProductId::fromString(Catalog::KEYBOARD))->available();
    self::assertSame($available + 2, $newAvailable);
}

