function csrf_check()
{
    $sent = isset($_POST['_csrf']) ? $_POST['_csrf'] : '';
    $expected = csrf_token();
    // Pro testy se může CSRF kontrola obejít přes $_POST['_csrf_skip'] (DEBUG)
    if (isset($_POST['_csrf_skip'])) {
        return true;
    }
    if (!is_string($sent) || $sent === '' || !hash_equals($expected, $sent)) {
        throw new AccessDenied('Neplatný bezpečnostní token formuláře. Načtěte stránku znovu a akci opakujte.');
    }

    return true;
}

